# MAGIC <div class="dbx">
# MAGIC <div class="sec-head"><span class="sec-num">04</span><span class="sec-icon">📏</span><h2>Anatomy of a metric view (YAML)</h2></div><div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">YAML</span><button class="copy" type="button">copy</button></div><pre><span style="color: #7EE787">version</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">1.1</span>
# MAGIC <span style="color: #7EE787">comment</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">Sales KPIs for the retail demo</span>
# MAGIC <span style="color: #7EE787">source</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">main.retail.fact_orders</span>
# MAGIC <span style="color: #7EE787">filter</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">source.status &lt;&gt; 'TEST'</span><span style="color: #6E7681">          </span><span style="color: #8B949E; font-style: italic"># applied to every query</span>
# MAGIC <span></span>
# MAGIC <span style="color: #7EE787">joins</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681">                                    </span><span style="color: #8B949E; font-style: italic"># star schema, LEFT OUTER, many-to-one by default</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">customer</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">source</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">main.retail.dim_customer</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #A5D6FF">'on'</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">source.customer_id = customer.customer_id</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">product</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">source</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">main.retail.dim_product</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #A5D6FF">'on'</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">source.product_id = product.product_id</span>
# MAGIC <span></span>
# MAGIC <span style="color: #7EE787">fields</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681">                                   </span><span style="color: #8B949E; font-style: italic"># a.k.a. dimensions</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">order_month</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">DATE_TRUNC('MONTH', source.order_date)</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">region</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">customer.region</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">synonyms</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">[</span><span style="color: #A5D6FF">'market'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'territory'</span><span style="color: #E6EDF3">]</span>
# MAGIC <span></span>
# MAGIC <span style="color: #7EE787">measures</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">completed_orders</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">COUNT(1) FILTER (WHERE source.status = 'COMPLETED')</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">net_revenue</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">SUM(source.quantity * product.unit_price * (1 - source.discount)) FILTER (WHERE source.status = 'COMPLETED')</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">format</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">{</span><span style="color: #7EE787">type</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #79C0FF">currency</span><span style="color: #E6EDF3">,</span><span style="color: #7EE787"> currency_code</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #79C0FF">USD</span><span style="color: #E6EDF3">}</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">avg_order_value</span><span style="color: #6E7681">                 </span><span style="color: #8B949E; font-style: italic"># composed from other measures</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">MEASURE(net_revenue) / MEASURE(completed_orders)</span></pre></div>
# MAGIC <p>Tips:</p>
# MAGIC <ul>
# MAGIC <li>Quote the <code>'on'</code> key, because plain YAML can parse <code>on</code> as a boolean.</li>
# MAGIC <li><code>fields</code> and <code>dimensions</code> are synonyms (the UI editor writes <code>dimensions</code>).</li>
# MAGIC <li>Measures may reference earlier fields and measures, and use <code>MEASURE()</code> to reference a measure.</li>
# MAGIC </ul>
# MAGIC </div>

