# MAGIC <span style="color: #6E7681">       </span><span style="color: #E6EDF3">MEASURE(avg_order_value)</span><span style="color: #6E7681">  </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">aov</span>
# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">sales_metrics</span>
# MAGIC <span style="color: #FF7B72">WHERE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">product_category</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'Electronics'</span>
# MAGIC <span style="color: #FF7B72">GROUP</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">BY</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">ALL</span>
# MAGIC <span style="color: #FF7B72">ORDER</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">BY</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">order_month;</span></pre></div>
# MAGIC <p>Rules to remember:</p>
# MAGIC <ul>
# MAGIC <li>Every measure <strong>must</strong> be wrapped in <code>MEASURE()</code> (on DBR 18.1+, <code>agg()</code> works as well).</li>
# MAGIC <li><strong>No <code>SELECT *</code></strong>: list fields explicitly.</li>
# MAGIC <li><strong>No direct joins</strong> with other tables. Aggregate in a CTE first, then join the CTE.</li>
# MAGIC <li><code>DESCRIBE TABLE EXTENDED sales_metrics AS JSON</code> shows the full YAML (<em>View Text</em>) and per-column metadata.</li>
# MAGIC <li>In AI/BI dashboards, <code>MEASURE()</code> is applied automatically.</li>
# MAGIC </ul>
# MAGIC </div>

