# MAGIC <div class="sec-head"><span class="sec-num">07</span><span class="sec-icon">🏷️</span><h2>Agent metadata: teach Genie your vocabulary</h2></div><p>YAML spec <strong>1.1</strong> (DBR 17.3+) adds metadata that downstream tools understand:</p>
# MAGIC <div class="tbl"><table>
# MAGIC <thead>
# MAGIC <tr>
# MAGIC <th>Property</th>
# MAGIC <th>What it does</th>
# MAGIC <th>Who uses it</th>
# MAGIC </tr>
# MAGIC </thead>
# MAGIC <tbody>
# MAGIC <tr>
# MAGIC <td><code>comment</code></td>
# MAGIC <td>Business description of the view / field / measure</td>
# MAGIC <td>Genie, Catalog, BI tools</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><code>display_name</code></td>
# MAGIC <td>Human-friendly label (≤ 255 chars)</td>
# MAGIC <td>Dashboards, BI tools</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><code>synonyms</code></td>
# MAGIC <td>Up to 10 alternative names</td>
# MAGIC <td><strong>Genie imports them automatically</strong></td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><code>format</code></td>
# MAGIC <td><code>number</code>, <code>currency</code>, <code>percentage</code>, <code>byte</code>, <code>date</code>, <code>date_time</code></td>
# MAGIC <td>Dashboards (auto-applied)</td>
# MAGIC </tr>
# MAGIC </tbody>
# MAGIC </table></div>
# MAGIC <div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">YAML</span><button class="copy" type="button">copy</button></div><pre><span style="color: #7EE787">measures</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">net_revenue</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">SUM(source.amount)</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">comment</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">Revenue after discounts, completed orders only</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">display_name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">Net Revenue</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">synonyms</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">[</span><span style="color: #A5D6FF">'revenue'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'sales'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'turnover'</span><span style="color: #E6EDF3">]</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">format</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #7EE787">type</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">currency</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #7EE787">currency_code</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">EUR</span>
