# MAGIC <div class="sec-head"><span class="sec-num">08</span><span class="sec-icon">📏</span><h2>Composability and window measures</h2></div><p><strong>Composability:</strong> build measures on measures:</p>
# MAGIC <div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">YAML</span><button class="copy" type="button">copy</button></div><pre><span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">revenue_per_customer</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">MEASURE(net_revenue) / MEASURE(unique_customers)</span></pre></div>
# MAGIC <p><strong>Window measures</strong> cover trailing, cumulative, and period-over-period values:</p>
# MAGIC <div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">YAML</span><button class="copy" type="button">copy</button></div><pre><span style="color: #6E7681">  </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">name</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">revenue_trailing_7d</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">expr</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">SUM(source.amount)</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">window</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">order</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">order_date</span><span style="color: #6E7681">        </span><span style="color: #8B949E; font-style: italic"># a field of the metric view</span>
# MAGIC <span style="color: #6E7681">        </span><span style="color: #7EE787">range</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">trailing 7 day</span><span style="color: #6E7681">    </span><span style="color: #8B949E; font-style: italic"># current | cumulative | trailing n unit | leading n unit | all</span>
# MAGIC <span style="color: #6E7681">        </span><span style="color: #7EE787">semiadditive</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">last</span></pre></div>
# MAGIC <ul>
# MAGIC <li><code>trailing</code> / <code>leading</code> are <strong>exclusive</strong> of the current row by default. <code>inclusive</code> needs DBR 18.1+ and spec 1.1.</li>
# MAGIC <li><code>offset: -12 month</code> gives "same period last year" (DBR 18.1+, spec 1.1).</li>
# MAGIC </ul>
# MAGIC </div>

