# MAGIC <td>DBR 17.3</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><strong>Materialization</strong></td>
# MAGIC <td>Pre-computed aggregates with automatic query rewrite, <code>schedule: every 6 hours</code></td>
# MAGIC <td>DBR 17.3</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><strong>Parameters</strong></td>
# MAGIC <td><code>sales_metrics(discount =&gt; 0.2)</code>, queried as a table-valued function</td>
# MAGIC <td>DBR 18.2</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td><strong>Wildcards</strong></td>
# MAGIC <td><code>- expr: source.* EXCEPT (comment)</code></td>
# MAGIC <td>DBR 18.2</td>
