# MAGIC dbxQuiz('dbxquiz', [{"q": "What is the main difference between a standard view and a metric view?", "o": ["A metric view is always materialized", "A metric view fixes the measure definition, while the grouping is chosen at query time", "A metric view can only be queried from dashboards", "A metric view does not support joins"], "c": 1, "e": "A standard view fixes both aggregation and GROUP BY. A metric view stores only the definitions, and the engine computes the measure correctly at whatever grain the query asks for."}, {"q": "A view stores unique_customers per month. Why is SUM(unique_customers) over a year wrong?", "o": ["SUM is not allowed on views", "Distinct counts are not additive: the same customer is counted in many months", "Because of NULL values", "It is correct"], "c": 1, "e": "COUNT(DISTINCT) is non-additive. A metric view recomputes it from detail rows for the requested grain."}, {"q": "Which query against a metric view is valid?", "o": ["`SELECT * FROM sales_metrics`", "`SELECT region, SUM(net_revenue) FROM sales_metrics GROUP BY region`", "`SELECT region, MEASURE(net_revenue) FROM sales_metrics GROUP BY region`", "`SELECT m.*, c.name FROM sales_metrics m JOIN customers c ON ...`"], "c": 2, "e": "Measures must be wrapped in MEASURE(). SELECT * and direct joins are not allowed (use a CTE for joins)."}, {"q": "Which agent metadata property does Genie import automatically to match user wording to fields and measures?", "o": ["format", "synonyms", "display_name", "materialization"], "c": 1, "e": "Synonyms (up to 10 per field or measure) are imported by Genie automatically. Formats and display names are mainly used by dashboards and BI tools."}, {"q": "You prototyped KPIs as a local metric view in an AI/BI dashboard. How do you make them available to a Genie Agent?", "o": ["Copy the dashboard", "Use 'Export as a metric view' to create a Unity Catalog metric view", "Genie can read local metric views directly", "It is not possible"], "c": 1, "e": "Local metric views are scoped to one dashboard. Exporting creates a governed UC metric view that Genie, SQL and BI tools can use."}]);
